class ShlOp(CombOp):
    OPERATION_NAME = "comb.shl"

    def evaluate(self, env: Optional[SignalEnv] = None) -> int:
        lhs, rhs = (self.read_operands(env or {}) + [0, 0])[:2]
        return self.truncate(lhs << rhs)


class ShrUOp(CombOp):
    OPERATION_NAME = "comb.shru"

    def evaluate(self, env: Optional[SignalEnv] = None) -> int:
        lhs, rhs = (self.read_operands(env or {}) + [0, 0])[:2]
        return self.truncate(lhs >> rhs)


class ShrSOp(CombOp):
    OPERATION_NAME = "comb.shrs"

    def evaluate(self, env: Optional[SignalEnv] = None) -> int:
        width = self.width
        lhs, rhs = (self.read_operands(env or {}) + [0, 0])[:2]
        return self.truncate(_to_signed(lhs, width) >> rhs)


class MuxOp(CombOp):
    """``comb.mux %cond, %true, %false : i4``."""

    OPERATION_NAME = "comb.mux"

    def evaluate(self, env: Optional[SignalEnv] = None) -> int:
        values = self.read_operands(env or {})
        if len(values) < 3:
            raise NotImplementedError("comb.mux needs cond, true and false operands")
        condition, when_true, when_false = values[0], values[1], values[2]
        return self.truncate(when_true if condition & 1 else when_false)

    def verify_op(self) -> List[str]:
        if self.num_operands != 3:
            return [f"'comb.mux' expects 3 operands, got {self.num_operands}"]
        return []


#: ``comb.icmp`` predicates.  Signed variants reinterpret the operands.
ICMP_PREDICATES: Dict[str, Callable[[int, int], bool]] = {
    "eq": lambda a, b: a == b,
    "ne": lambda a, b: a != b,
    "ult": lambda a, b: a < b,
    "ule": lambda a, b: a <= b,
    "ugt": lambda a, b: a > b,
    "uge": lambda a, b: a >= b,
    "slt": lambda a, b: a < b,
    "sle": lambda a, b: a <= b,
    "sgt": lambda a, b: a > b,
    "sge": lambda a, b: a >= b,
}

_SIGNED_PREDICATES = frozenset({"slt", "sle", "sgt", "sge"})


class ICmpOp(CombOp):
    """``comb.icmp eq %a, %b : i2`` producing an ``i1``."""

    OPERATION_NAME = "comb.icmp"

    def __init__(
        self,
        predicate: str = "eq",
        operands: Optional[Sequence[Union[Value, str]]] = None,
        width: int = 0,
        result_name: str = "",
        result_types: Optional[Sequence[Type]] = None,
        attributes: Optional[Dict[str, Attribute]] = None,
        location: Optional[Location] = None,
    ) -> None:
        attrs: Dict[str, Attribute] = dict(attributes or {})
        attrs.setdefault("predicate", StringAttr(predicate))
        super().__init__(
            operands=operands,
            result_types=list(result_types or ()) or [IntegerType(1)],
            attributes=attrs,
            width=width,
            result_name=result_name,
            location=location,
        )
        #: The operand width; the *result* is always one bit.
        self.operand_width = int(width)

    @classmethod
    def result_types_from_trailing(
        cls, trailing_types: Sequence[Type], num_results: int
    ) -> List[Type]:
        return [IntegerType(1)] * num_results

    @property
    def predicate(self) -> str:
        attr = self.attributes.get("predicate")
        return attr.value if attr is not None else "eq"

    def infer_width(self, type_env: Optional[Dict[str, int]] = None) -> int:
        return 1

    def _comparison_width(self) -> int:
        for operand in self.ssa_operands:
            width = bit_width_of(operand.type)
            if width:
                return width
        return self.operand_width

    def evaluate(self, env: Optional[SignalEnv] = None) -> int:
        predicate = self.predicate
        compare = ICMP_PREDICATES.get(predicate)
        if compare is None:
            return 0
        values = self.read_operands(env or {})
        if len(values) < 2:
            return 0
        lhs, rhs = values[0], values[1]
        if predicate in _SIGNED_PREDICATES:
            width = self._comparison_width()
            lhs = _to_signed(lhs, width)
            rhs = _to_signed(rhs, width)
        return 1 if compare(lhs, rhs) else 0

    def verify_op(self) -> List[str]:
        if self.predicate not in ICMP_PREDICATES:
            return [f"'comb.icmp' has unknown predicate {self.predicate!r}"]
        return []


class ConcatOp(CombOp):
    """``comb.concat %hi, %lo`` - operand 0 becomes the most significant bits."""

    OPERATION_NAME = "comb.concat"

    def __init__(
        self,
        operands: Optional[Sequence[Union[Value, str]]] = None,
        operand_widths: Optional[Sequence[int]] = None,
        width: int = 0,
        result_name: str = "",
        result_types: Optional[Sequence[Type]] = None,
        location: Optional[Location] = None,
    ) -> None:
        super().__init__(
            operands=operands,
            result_types=result_types,
            width=width,
            result_name=result_name,
            location=location,
        )
        self.operand_widths: List[int] = list(operand_widths or ())

    @classmethod
    def build_parsed(cls, **kwargs: Any) -> Operation:
        op = super().build_parsed(**kwargs)
        op.operand_widths = []
        return op

    def _widths(self) -> List[int]:
        if self.operand_widths:
            return list(self.operand_widths)
        return [bit_width_of(v.type) for v in self.ssa_operands]

    def infer_width(self, type_env: Optional[Dict[str, int]] = None) -> int:
        widths = self._widths()
        return sum(widths) if widths else self.width

    def evaluate(self, env: Optional[SignalEnv] = None) -> int:
        values = self.read_operands(env or {})
        widths = self._widths()
        packed = 0
        for index, value in enumerate(values):
            width = widths[index] if index < len(widths) else 1
            packed = (packed << width) | (value & ((1 << width) - 1))
        total = sum(widths) if widths else self.width
        return packed & ((1 << total) - 1) if total else packed


class ExtractOp(CombOp):
    """``comb.extract %x from 3 : (i8) -> i4``."""

    OPERATION_NAME = "comb.extract"

    def __init__(
        self,
        operands: Optional[Sequence[Union[Value, str]]] = None,
        low_bit: int = 0,
        width: int = 0,
        result_name: str = "",
        result_types: Optional[Sequence[Type]] = None,
        location: Optional[Location] = None,
    ) -> None:

    def read_all(self, op: Operation, config: KConfiguration) -> List[int]:
        return [self.read(op, config, index) for index in range(len(op.operands))]

    # -- result handling --------------------------------------------------
    def width(self, op: Operation) -> int:
        return _result_width(op)

    def truncate(self, op: Operation, value: int) -> int:
        width = self.width(op)
        return int(value) & ((1 << width) - 1) if width > 0 else int(value)

    def bind(self, op: Operation, config: KConfiguration, value: int) -> int:
        """Bind ``value`` to every result of ``op`` (and to its SSA name)."""
        for result in op.results:
            config.bind(result, value)
            if result.name:
                config.bind(result.name, value)
        return value

    def label(self, op: Operation) -> str:
        names = [f"%{r.name}" for r in op.results if r.name]
        return ", ".join(names)

    # -- application ------------------------------------------------------
    def compute(self, op: Operation, config: KConfiguration) -> int:
        """The rule's arithmetic.  Overridden by every concrete rule."""
        raise NotImplementedError(f"{self.NAME} does not implement compute()")

    def apply(
        self, op: Optional[Operation], config: KConfiguration
    ) -> RuleApplication:
        """Fire the rule, rewriting ``config``, and return the trace record."""
        assert op is not None, f"{self.NAME} needs an operation"
        operands = tuple(self.read_all(op, config))
        value = self.truncate(op, self.compute(op, config))
        self.bind(op, config, value)
        return RuleApplication(
            rule=self.NAME,
            op_name=op.name,
            label=self.label(op),
            operands=operands,
            result=value,
            cycle=config.cycle,
            phase=self.PHASE,
        )

    # -- reporting --------------------------------------------------------
    def describe(self) -> str:
        rule = self.K_RULE.strip() or f"rule {self.NAME}"
        targets = ", ".join(self.OP_NAMES) or "<configuration>"
        return f"{self.NAME} [{self.PHASE.value}] on {targets}\n    {rule}"

    def __repr__(self) -> str:  # pragma: no cover - debugging helper
        return f"<{type(self).__name__} {self.NAME!r}>"


class ConfigurationRule(SemanticRule):
