class FirRegOp(SeqOp):
    """``seq.firreg`` - a FIRRTL-style register with an optional preset."""

    OPERATION_NAME = "seq.firreg"

    INPUT = 0
    CLOCK = 1
    RESET = 2
    RESET_VALUE = 3

    def __init__(
        self,
        name: Optional[str] = None,
        width: int = 0,
        clock: Union[Value, str] = "clk",
        reset: Optional[Union[Value, str]] = None,
        reset_value: int = 0,
        preset_value: Optional[int] = None,
        current_value: int = 0,
        input_signal: Optional[Union[Value, str]] = None,
        operands: Optional[Sequence[Union[Value, str]]] = None,
        result_types: Optional[Sequence[Type]] = None,
        location: Optional[Location] = None,
    ) -> None:
        ops: List[Union[Value, str]] = list(operands or ())
        if not ops:
            if input_signal is not None:
                ops.append(input_signal)
            ops.append(clock)
            if reset is not None:
                ops.append(reset)
        super().__init__(
            operands=ops,
            result_types=result_types,
            width=width,
            result_name=name or "",
            location=location,
        )
        self.reg_name = name or ""
        self.reset_value = int(reset_value)
        self.preset_value = preset_value
        self.current_value = int(preset_value if preset_value is not None else current_value)
        self.cycles_ticked = 0

    @classmethod
    def build_parsed(cls, **kwargs: Any) -> Operation:
        op = super().build_parsed(**kwargs)
        op.preset_value = None
        op.reset_value = 0
        op.current_value = 0
        op.cycles_ticked = 0
        return op

    def preset(self) -> None:
        if self.preset_value is not None:
            self.current_value = self.truncate(self.preset_value)

    def next_value(self, env: SignalEnv) -> int:
        if self.num_operands > self.RESET and self.read_operand(env, self.RESET) & 1:
            if self.num_operands > self.RESET_VALUE:
                return self.truncate(self.read_operand(env, self.RESET_VALUE))
            return self.truncate(self.reset_value)
        return self.truncate(self.read_operand(env, self.INPUT))

    def tick(self, env: Optional[SignalEnv] = None, next_value: Optional[int] = None) -> int:
        """Commit ``next_value`` if given, otherwise compute it from ``env``."""
        if next_value is not None:
            return self.commit(next_value)
        return self.commit(self.next_value(env or {}))


@dataclass
class ShiftRegOp:
    """``seq.shiftreg`` - a chain of ``length`` registers."""

    name: str
    width: int = 1
    length: int = 1
    clock: str = "clk"
    stages: List[int] = field(default_factory=list)

    def __post_init__(self) -> None:
        if not self.stages:
            self.stages = [0] * self.length

    def mask(self) -> int:
        return (1 << self.width) - 1 if self.width > 0 else 0

    def shift_in(self, value: int) -> int:
        """Push ``value`` in at stage 0 and return what falls out of the end."""
        shifted_out = self.stages[-1] if self.stages else 0
        self.stages = [int(value) & self.mask()] + self.stages[:-1]
        return shifted_out

    def peek(self, stage: int) -> int:
        if stage < 0 or stage >= len(self.stages):
            return 0
        return self.stages[stage]

    def reset_all(self) -> None:
        self.stages = [0] * self.length


@dataclass
class FIFOOp:
    """``seq.fifo`` - a circular-buffer FIFO."""

    name: str
    width: int = 32
    depth: int = 16
    clock: str = "clk"
    reset: Optional[str] = None
    buffer: List[int] = field(default_factory=list)
    read_ptr: int = 0
    write_ptr: int = 0
    count: int = 0

    def __post_init__(self) -> None:
        if not self.buffer:
            self.buffer = [0] * self.depth

    def is_full(self) -> bool:
        return self.count >= self.depth

    def is_empty(self) -> bool:
        return self.count == 0

    def occupancy(self) -> int:
        return self.count

    def push(self, value: int) -> bool:
        if self.is_full():
            return False
        self.buffer[self.write_ptr] = int(value) & ((1 << self.width) - 1)
        self.write_ptr = (self.write_ptr + 1) % self.depth
        self.count += 1
        return True

    def pop(self) -> Optional[int]:
        if self.is_empty():
            return None
        value = self.buffer[self.read_ptr]
        self.read_ptr = (self.read_ptr + 1) % self.depth
        self.count -= 1
        return value

